  const rooms=`<div class="fl-rooms" role="tablist">${F().plan(st).rooms.map(x=>`<button type="button" role="tab" class="fl-room-chip" data-action="ps-room" data-id="${e(x.id)}" aria-selected="${ui.room===x.id}">${e(x.name)}<em>${F().plan(st).tables.filter(t=>t.room===x.id).length}</em></button>`).join('')}</div>`;
  const map=`<section class="panel fl-map ps-map is-sections">${rooms}${r?`<div class="fl-canvas-wrap"><div class="fl-canvas ps-canvas" style="--cols:${r.cols};--rows:${r.rows}" role="group" aria-label="${e(r.name)} tables">${F().plan(st).tables.filter(t=>t.room===r.id).map(tableEl).join('')}</div></div>`:''}<div class="fl-map-foot"><small class="fl-hint">${ui.secPerson?'Tapping a table gives it to '+e(first(ui.secPerson))+'.':'Tap a table to clear it, or pick a server above.'}</small><div class="toolbar">${btn('Auto-assign','sec-auto','','secondary small')}${Object.keys(sec).length?btn('Clear','sec-clear','','quiet small'):''}</div></div></section>`;
  const list=`<section class="panel fl-arrivals"><div class="fl-arrivals-head"><h3>${e(st.service)} sections</h3></div><div class="sk-card">${byPerson.map(x=>`<div class="sk-row ps-jrow"><span class="sk-row-main"><span class="sk-row-text"><strong>${srv(x.pid)} ${e(name(x.pid))}</strong><small><span>${x.tables.length?'Tables '+e(x.tables.join(', ')):'No tables yet'}</span></small></span></span></div>`).join('')||'<p class="sk-hint">Nobody is rostered on this service.</p>'}</div></section>`;
  return `<div class="ps-toolbar">${when()}<span class="ps-when">Pick a server, then tap tables</span></div>${chips}<div class="ps-layout"><div class="ps-map-col">${map}</div>${list}</div>`;
