 function drawerOpenDialog(){const st=s();open('Open the '+st.service+' drawer',`<p class="sk-dialog-meta">${e(dateLabel(st.date,{weekday:'short',month:'short',day:'numeric'}))} · ${e(st.service)}</p>${input('float','Starting float',st.pos.settings.cashFloat.toFixed(2),'number','required min="0" step="0.01" inputmode="decimal"')}${padHtml('float')}<p class="sk-hint">Count the float before the first guest. Everything cash goes through this drawer until it is closed.</p>`,{type:'drawer-open'},true,'Open drawer');}
